{
  "technical_and_design_decisions": [
    "Use Spring Integration / Spring Messaging infrastructure for native WebSocket sink implementation.",
    "Utilize standard Hadoop FileSystem API (HDFS) for retrieving and staging custom module uber-jars.",
    "Implement classloader isolation using standard parent-last or custom module classloader delegation strategy for xd/lib shared jars vs. module-bundled jars.",
    "Configure SonarQube / PMD plugins at the root Gradle build level and configure Sonar webhooks/notifications for committer alerts on violations.",
    "Leverage PowerShell scripting on Bamboo Windows build agents to orchestrate background service dependencies (Redis, RabbitMQ) and execute integration test suites via standard `./gradlew` commands."
  ],
  "assumptions": [
    "A single full-stack/DevOps Java developer will perform all design, implementation, CI setup, and testing work sequentially.",
    "Bamboo CI server and EC2 build instances have appropriate network access and admin permissions to install and configure software services.",
    "An HDFS cluster or compatible Hadoop endpoint is accessible for hosting and fetching module uber-jars.",
    "Java 17+ and Gradle build environment are pre-configured on all CI nodes."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Documentation for Custom Module Standards (U1)",
      "activity_description": "Author developer guides, standards, and recommended architectural patterns for creating custom uber-jar modules.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "HDFS Module Hosting and Deployment Support (U2)",
      "activity_description": "Implement HDFS module repository fetcher, enabling container deployment directly from HDFS-hosted custom uber-jars, including unit and integration tests.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Native WebSocket Sink Implementation (U3)",
      "activity_description": "Develop native WebSocket sink component supporting full-duplex TCP communications, configuration properties, payload handling, and test cases.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "CI Dependency Caching Research & Integration (U4)",
      "activity_description": "Evaluate and implement npm-cache for caching frontend/UI dependencies in CI build scripts to improve build speed and stability.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "EC2 CI Build Infrastructure & Gradle Enhancements (U5)",
      "activity_description": "Update EC2 CI configurations: enable distributed JVM tests, switch to ./gradlew command tasks, disable embedded Hadoop in relevant tests, and enable maxParallelForks.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "PMD/Sonar Violation Fixes & Notification Setup (U6)",
      "activity_description": "Investigate WARN logs, fix PMD and Sonar violations across codebase, and configure Sonar notification rules to notify committers of quality gate failures.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Windows CI Infrastructure & Automated Integration Tests (U7)",
      "activity_description": "Configure Bamboo Windows environment, write PowerShell scripts to setup Redis, RabbitMQ services, and automate integration test triggers.",
      "most_likely_effort": 26
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Shared Library (xd/lib) & Classloader Hierarchy Support (U8)",
      "activity_description": "Implement support for common shared jars in xd/lib and establish classloading isolation/fallback rules to prevent jar version conflicts across custom modules.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "End-to-End System Testing & Verification",
      "activity_description": "Perform overall regression testing, validate CI pipeline execution on Windows and EC2, and verify custom module deployment from HDFS.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 190
  }
}
